:root{--ink:#1b354f;--green:#185e94;--red:#b21f32;--muted:#5d6e7c;--line:#d3e2ed;--paper:#fff;background:#f1f7fb}.nav{background:#f1f7fb}.source-paragraph h3,.para-name{color:var(--green)}.hero{display:grid;grid-template-columns:1.1fr .8fr;gap:38px;align-items:center;padding:24px 0 40px}.hero h1{font-size:54px;line-height:1.3}.lead{font-size:25px;line-height:1.7}.cover-panel{max-height:460px;overflow:hidden;border-radius:16px;border:1px solid var(--line)}.cover-panel img{width:100%;display:block}.resource-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.resource-grid a{text-decoration:none}.resource-grid h2{font-size:25px}.identity-banner{margin:16px 24px}.identity-banner summary{padding:10px}.identity-banner .identity{max-width:1000px;margin:auto}.answer-section,.teacher-page .paper,.reread{margin:20px 0}.whole-comic{max-width:900px;margin:28px auto}.whole-comic img{width:100%;height:auto}.whole-comic figcaption{text-align:center}.own-summary{font-family:LessonKai,serif;table-layout:fixed;font-size:19px}.own-summary th:first-child{width:23%}.own-summary td{overflow-wrap:anywhere}.paper select[data-field]{width:100%;font-family:LessonKai,serif;font-size:21px}.answer-label{margin-top:20px}.model{white-space:pre-wrap}#projector{background:#102438}#slideImage{display:block;width:100%;height:auto}#projector:fullscreen{display:flex;align-items:center;justify-content:center}#projector:fullscreen img{max-height:100vh;object-fit:contain}#notes{white-space:pre-wrap}#slideSelect{max-width:44vw}.teacher-page table td{vertical-align:top}.paper{margin-bottom:18px}
@media(max-width:760px){.hero{grid-template-columns:1fr}.cover-panel{max-height:340px}.resource-grid{grid-template-columns:1fr}.hero h1{font-size:38px}.paper select[data-field]{font-size:18px}.own-summary{font-size:17px}main{padding:18px 14px 50px}.paper{padding:20px}}

.thread-table{font-family:LessonKai,serif;font-size:20px}.thread-table th{width:58px}.thread-table td{line-height:1.8}.thread-word{color:#b21f32;font-weight:bold}.read-intro{margin-top:20px}.image-index{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.image-index img{width:100%}.hero .panel{max-width:540px}.mode-notes{max-width:900px;line-height:1.8}.resource-grid{grid-template-columns:repeat(2,1fr)}@media(max-width:760px){.resource-grid{grid-template-columns:1fr}.thread-table{font-size:18px}}

(()=>{'use strict';
const L=window.LESSON,activity=document.querySelector('#activity'),source=document.querySelector('#source');
function enhance(){
 const select=document.querySelector('[data-field="thread"]');
 if(select&&!document.querySelector('#threadTable')){
  const section=document.createElement('section');section.id='threadTable';
  const h=document.createElement('h3');h.textContent='课本七行内容';section.append(h);
  const table=document.createElement('table');table.className='thread-table';
  for(const [p,text] of L.threadRows){const tr=document.createElement('tr'),th=document.createElement('th'),td=document.createElement('td');th.textContent='第'+p+'段';td.textContent=text;tr.append(th,td);table.append(tr)}section.append(table);
  const map=document.createElement('p');map.className='kai';map.id='threadMap';section.append(map);
  const label=select.previousElementSibling,choice=activity.querySelector('fieldset');
  if(choice)choice.before(section,label,select);else label.before(section);
  const sync=()=>{map.textContent='情节概括：包〔'+(select.value||'　　')+'〕 → 传〔'+(select.value||'　　')+'〕 → 吃到〔'+(select.value||'　　')+'〕。';};select.addEventListener('change',sync);sync();
 }
 if(document.querySelector('#p1')&&window.LessonEngine.state().position.view==='read'&&!document.querySelector('#firstOral')){
  const d=document.createElement('details');d.id='firstOral';d.className='read-intro';const s=document.createElement('summary');s.textContent='口头想一想';const p=document.createElement('p');p.textContent='中国北方人为什么喜欢在大年三十吃饺子？先说你的想法。';d.append(s,p);source.append(d);
 }
}
new MutationObserver(enhance).observe(activity,{childList:true});enhance();
})();

